import { JsonValueSchema, type JsonValue } from "@aventurevc/api-schemas/http/json-value";
import openApiDocument from "../../postman/openapi.json";
import { authMaterializationFailure, materializeAuth } from "./auth-resolver";
import {
  type AventureMethod,
  aventureRequest,
  problemFailure,
  responseWarningMetadata,
} from "./client";
import { type AuthScope, prepareCallEnv, type PrepareScope } from "./env";
import { resolveAgentProvenanceSearchParams, type AgentClient } from "./agent-provenance";
import {
  OpenApiDocumentSchema,
  buildOpenApiTemplatePath,
  findOperationByOperationId,
  operationFilterMetadata,
  pathWithoutQuery,
  resolveOpenApiEndpoint as resolveDocumentEndpoint,
  type OpenApiLocatedOperation,
  type OpenApiMethod,
  type OpenApiOperation,
  type OpenApiSearchParams,
} from "./openapi-document";
import { prepareOpenApiRequestBody } from "./request-body";
import {
  failure,
  pageMetadata,
  responseCount,
  type ResultEnvelope,
  success,
} from "./result-envelope";
import { privateReadbackMode } from "./private-readback";

let authMaterialized = false;

export type ApiAuthMode = "auto" | "read" | "write" | "bearer" | "none";
export type OpenApiResponseFormat = "auto" | "json" | "text";

export interface OpenApiCallInput {
  readonly method: AventureMethod;
  readonly path: string;
  readonly searchParams?: OpenApiSearchParams;
  readonly body?: JsonValue;
  readonly contentType?: string;
  readonly auth: ApiAuthMode;
  readonly execute: boolean;
  readonly dryRunMetadata?: OpenApiDryRunMetadata;
  readonly requesterScope?: AuthScope;
  readonly responseFormat?: OpenApiResponseFormat;
  readonly clientInfo?: AgentClient;
}

interface OpenApiDryRunMetadata {
  readonly bodySchemaName: string | null;
  readonly bodyKind: string | null;
  readonly bodyRequired: boolean;
  readonly requiredBodyPath: readonly string[];
}

interface OpenApiCallResult extends Partial<OpenApiDryRunMetadata> {
  readonly method: AventureMethod;
  readonly endpoint: string;
  readonly httpStatus?: number;
  readonly operationId: string | undefined;
  readonly summary: string | undefined;
  readonly nextCursor?: string;
  readonly response: JsonValue | undefined;
}

export type OpenApiCallContent = OpenApiCallResult | string | null;

export interface OpenApiOperationSelector {
  readonly operationId?: string;
  readonly method?: AventureMethod;
  readonly path?: string;
  readonly pathParams?: Record<string, string | number>;
}

const apiParse = OpenApiDocumentSchema.safeParse(openApiDocument);
if (!apiParse.success)
  throw new Error(`OpenAPI snapshot drifted from spec subset: ${apiParse.error.message}`);
const api = apiParse.data;
const LOOPBACK_HOSTS = ["localhost", "127.0.0.1", "0.0.0.0", "[::1]"] as const;
const JOB_NAME_HEADER = "X-Job-Name";
const JOB_NAME_ENV = "AVENTURE_JOB_NAME";
const JOB_NAME_PATTERN = /^[A-Za-z0-9._:-]{1,120}$/;

export function buildOpenApiPath(
  operationId: string,
  pathParams: Record<string, string | number>,
): string {
  const endpoint = findOperationByOperationId(api.paths, operationId);
  if (!endpoint) throw new Error(`OpenAPI operationId not found: ${operationId}`);
  return buildOpenApiTemplatePath(endpoint.template, pathParams, operationId);
}

/** Resolve a single required OpenAPI header without duplicating its Kotlin-owned name in the CLI. */
export function buildRequiredOpenApiHeader(operationId: string): string {
  const endpoint = findOperationByOperationId(api.paths, operationId);
  if (!endpoint) throw new Error(`OpenAPI operationId not found: ${operationId}`);
  const requiredHeaders = (endpoint.operation.parameters ?? []).filter(
    (parameter) => parameter.in === "header" && parameter.required === true,
  );
  if (requiredHeaders.length !== 1) {
    throw new Error(
      `OpenAPI operation ${operationId} must declare exactly one required header parameter; found ${requiredHeaders.length}`,
    );
  }
  const name = requiredHeaders[0]?.name.trim();
  if (!name) throw new Error(`OpenAPI operation ${operationId} has a blank required header name`);
  return name;
}

export function resolveOpenApiOperationSelector(
  selector: OpenApiOperationSelector,
): ResultEnvelope<(OpenApiLocatedOperation & { readonly path: string }) | null> {
  const pathParams = selector.pathParams ?? {};
  try {
    if (selector.operationId !== undefined) {
      const endpoint = findOperationByOperationId(api.paths, selector.operationId);
      if (endpoint === null) {
        return failure(`OpenAPI operationId not found: ${selector.operationId}`);
      }
      const path = buildOpenApiTemplatePath(endpoint.template, pathParams, selector.operationId);
      return success(`Resolved ${selector.operationId}`, { ...endpoint, path });
    }
    if (selector.method === undefined || selector.path === undefined) {
      return failure("Pass operationId or method+path.");
    }
    const rawPath = buildOpenApiTemplatePath(selector.path, pathParams, selector.path);
    const endpoint = resolveDocumentEndpoint(
      api.paths,
      selector.method.toLowerCase() as OpenApiMethod,
      rawPath,
    );
    if (endpoint === null) {
      return failure(
        `OpenAPI operation not found for ${selector.method} ${pathWithoutQuery(rawPath)}`,
      );
    }
    return success(`Resolved ${endpoint.operation.operationId}`, { ...endpoint, path: rawPath });
  } catch (error) {
    return failure((error as Error).message);
  }
}

export async function runOpenApiCall(
  input: OpenApiCallInput,
): Promise<ResultEnvelope<OpenApiCallContent>> {
  if (!authMaterialized) {
    await materializeAuth();
    authMaterialized = true;
  }
  const endpoint = resolveDocumentEndpoint(
    api.paths,
    input.method.toLowerCase() as OpenApiMethod,
    input.path,
  );
  if (!endpoint) {
    return failure(
      `OpenAPI operation not found for ${input.method} ${pathWithoutQuery(input.path)}`,
      [
        "Use a path emitted by postman/openapi.json; this CLI/MCP path intentionally does not call undocumented routes.",
      ],
    );
  }

  const operation = endpoint.operation;
  const requesterScope: AuthScope = input.requesterScope ?? "write";
  let upstreamMode: PrepareScope = input.auth === "auto" ? "none" : input.auth;
  if (input.auth === "auto") {
    const schemes = new Set(operation.security?.flatMap(Object.keys) ?? []);
    if (input.method === "GET" && schemes.has("clientSecretAuth")) upstreamMode = "read";
    else if (schemes.has("adminApiKeyAuth")) upstreamMode = "write";
    else if (schemes.has("bearerAuth")) upstreamMode = "bearer";
    else if (schemes.has("clientSecretAuth")) upstreamMode = "read";
  }
  if (requesterScope === "read" && (upstreamMode === "write" || upstreamMode === "bearer")) {
    return failure(
      "MCP transport credential is read-only (CLIENT_SECRET); refused write-scope upstream call.",
      [
        `Resolved upstream auth=${upstreamMode} for ${input.method} ${input.path}.`,
        "Pass auth='read' explicitly for POST read endpoints, or invoke with X-API-Key (ADMIN_API_KEY) for writes.",
      ],
    );
  }

  const normalizedBody = normalizeJsonStringBody(input.body);
  if (!normalizedBody.ok) return failure(normalizedBody.summary, normalizedBody.warnings);
  const prep = prepareOpenApiCallEnv(upstreamMode, requesterScope, operation, {
    searchParams: input.searchParams,
    body: normalizedBody.data,
  });
  if (!prep.ok || !prep.data) return failure(prep.summary, withMaterializationCause(prep.warnings));
  const { env, headers } = prep.data;

  const agentProvenance = resolveAgentProvenanceSearchParams({
    operation,
    searchParams: input.searchParams,
    clientInfo: input.clientInfo,
  });
  if (!agentProvenance.ok) return failure(agentProvenance.summary, agentProvenance.warnings);
  const resolvedSearchParams = agentProvenance.data ?? undefined;
  const requestPath = withSearchParams(input.path, resolvedSearchParams);
  const host = env.host.trim();
  const lowerHost = host.toLowerCase();
  const protocol = LOOPBACK_HOSTS.some(
    (loopback) => lowerHost === loopback || lowerHost.startsWith(`${loopback}:`),
  )
    ? "http"
    : "https";
  const requestHost = /^https?:\/\//i.test(host) ? host : `${protocol}://${host}`;
  const requestEnv = requestHost === env.host ? env : { ...env, host: requestHost };
  const operationId = operation.operationId;
  const operationMetadata = { method: input.method, endpoint: requestPath, operationId };
  const isWriteScope = upstreamMode === "write" || upstreamMode === "bearer";
  if (isWriteScope && input.method !== "GET" && !input.execute) {
    // One loud, machine-checkable notice, threaded into every output mode (summary + envelope
    // warnings for --text/--json/stderr, and the --data payload) so a write-scope dry-run preview
    // is never mistaken for a committed mutation. Placeholder ids live under `preview`, never top-level.
    const notPersistedNotice = `PREVIEW ONLY — NOT PERSISTED. The endpoint was NOT called and nothing was written (would ${input.method} ${requestPath}). Any ids under \`preview\` are placeholders, not real records. Re-run with --execute to persist.`;
    return success(
      notPersistedNotice,
      {
        dryRun: true,
        persisted: false,
        warning: notPersistedNotice,
        ...operationMetadata,
        summary: operation.summary,
        preview: input.dryRunMetadata ?? null,
        response: undefined,
      },
      {
        ...operationMetadata,
        references: [`${input.method} ${requestHost}${requestPath}`],
        warnings: [notPersistedNotice],
      },
    );
  }

  const requestBody = await prepareOpenApiRequestBody(
    operation,
    normalizedBody.data,
    input.contentType ?? defaultContentType(input.method),
  );
  if (!requestBody.ok || requestBody.data === null)
    return failure(requestBody.summary, requestBody.warnings);
  const accept = acceptHeader(input.responseFormat ?? "auto", operation);
  const jobName = process.env[JOB_NAME_ENV]?.trim();
  const response = await aventureRequest(
    requestEnv,
    {
      method: input.method,
      path: requestPath,
      headers: {
        ...headers,
        ...(jobName && JOB_NAME_PATTERN.test(jobName) ? { [JOB_NAME_HEADER]: jobName } : {}),
        Accept: accept,
      },
      body: requestBody.data.body,
      contentType: requestBody.data.contentType,
    },
    JsonValueSchema,
  );
  if (!response.ok) {
    return problemFailure(`${operationId ?? input.method} failed`, response.problem, [
      `endpoint=${requestPath}`,
    ]);
  }
  const page = pageMetadata(response.data);
  const warning = responseWarningMetadata(response.headers);
  return success(
    `${operationId ?? input.method} succeeded`,
    accept === "text/plain" && typeof response.data === "string"
      ? response.data
      : {
          ...operationMetadata,
          httpStatus: response.status,
          summary: operation.summary,
          nextCursor: response.headers["x-next-cursor"] || undefined,
          response: response.data as JsonValue | undefined,
        },
    {
      httpStatus: response.status,
      ...operationMetadata,
      format: accept === "text/plain" ? "text" : "json",
      count: responseCount(response.data, page),
      page,
      filters: operationFilterMetadata(operation, resolvedSearchParams),
      omitted: warning.omitted,
      references: [`${requestHost}${requestPath}`],
      warnings: warning.warnings,
    },
  );
}

function normalizeJsonStringBody(
  body: JsonValue | undefined,
): ResultEnvelope<JsonValue | undefined> {
  if (typeof body !== "string") return success("Request body unchanged", body);
  const first = body.trimStart().slice(0, 1);
  if (first !== "{" && first !== "[") return success("Request body unchanged", body);
  try {
    const parsed = JsonValueSchema.safeParse(JSON.parse(body));
    return parsed.success
      ? success("Request body parsed", parsed.data)
      : failure(`Request body string must be valid JSON: ${parsed.error.message}`);
  } catch (error) {
    return failure(`Request body string must be valid JSON: ${(error as Error).message}`);
  }
}

/**
 * An auth-scope failure ("… is required for …") states which credential the
 * call needed, never why it was absent. When saved auth failed to materialize,
 * that IS the cause, and reporting only the requirement reads as "not
 * configured in Doppler" — the misdiagnosis that sends callers rotating
 * secrets or waiting out rate limits instead of fixing the resolution.
 */
function withMaterializationCause(warnings: readonly string[]): string[] {
  const failedMaterialization = authMaterializationFailure();
  if (!failedMaterialization) return [...warnings];
  return [
    ...warnings,
    `Saved auth never materialized (config ${failedMaterialization.configPath}): ${failedMaterialization.reason}. The credential is UNRESOLVED, which is not evidence that it is missing from Doppler; check that the \`doppler\` binary is on PATH and the config is readable.`,
  ];
}

function prepareOpenApiCallEnv(
  upstreamMode: PrepareScope,
  requesterScope: AuthScope,
  operation: OpenApiOperation,
  input: Pick<OpenApiCallInput, "searchParams" | "body">,
): ReturnType<typeof prepareCallEnv> {
  const privateReadback = privateReadbackMode(operation, input.searchParams, input.body);
  if (upstreamMode === "read" && requesterScope === "write" && privateReadback !== "none") {
    const writePrep = prepareCallEnv("write");
    if (writePrep.ok) return writePrep;
    return privateReadback === "required" ? writePrep : prepareCallEnv("read");
  }
  const prep = prepareCallEnv(upstreamMode);
  if (prep.ok || upstreamMode !== "read" || requesterScope !== "write") return prep;
  const writePrep = prepareCallEnv("write");
  return writePrep.ok ? writePrep : prep;
}

function defaultContentType(method: AventureMethod): string | undefined {
  if (method === "PATCH") return "application/merge-patch+json";
  return method === "POST" || method === "PUT" ? "application/json" : undefined;
}

export function acceptHeader(format: OpenApiResponseFormat, operation: OpenApiOperation): string {
  if (format === "json") return "application/json";
  if (format === "text") return "text/plain";
  return Object.entries(operation.responses).some(
    ([status, response]) => status.startsWith("2") && "text/plain" in (response.content ?? {}),
  )
    ? "text/plain"
    : "application/json";
}

function withSearchParams(path: string, searchParams: OpenApiSearchParams | undefined): string {
  const url = new URL(path, "https://placeholder.invalid");
  for (const [key, value] of Object.entries(searchParams ?? {})) {
    if (value === undefined) continue;
    if (Array.isArray(value)) for (const item of value) url.searchParams.append(key, String(item));
    else url.searchParams.set(key, String(value));
  }
  return `${url.pathname}${url.search}`;
}
