import { JsonValueSchema, type JsonValue } from "@aventurevc/api-schemas/http/json-value";
import { Option } from "commander";
import { z } from "zod/v4";
import type { ResultEnvelopeFilters, ResultEnvelopeScalar } from "./result-envelope";

export const OPENAPI_METHODS = ["get", "post", "put", "patch", "delete"] as const;
export type OpenApiMethod = (typeof OPENAPI_METHODS)[number];
export type OpenApiVisibility = "private" | { readonly scope?: string; readonly value?: string };
export const OPENAPI_CLI_COMPOSITE_ROLES = ["start", "poll", "acknowledge", "revoke"] as const;

export interface OpenApiShape {
  readonly $ref?: string;
  readonly description?: string;
  readonly type?: string | readonly string[];
  readonly format?: string;
  readonly default?: JsonValue;
  readonly enum?: readonly JsonValue[];
  readonly readOnly?: boolean;
  readonly items?: OpenApiShape;
  readonly minItems?: number;
  readonly maxItems?: number;
  readonly properties?: Record<string, OpenApiShape>;
  readonly required?: readonly string[];
  readonly oneOf?: readonly OpenApiShape[];
  readonly anyOf?: readonly OpenApiShape[];
  readonly allOf?: readonly OpenApiShape[];
  readonly "x-aventure-visibility"?: OpenApiVisibility;
  readonly "x-aventure-cli-conflicts"?: readonly (readonly string[])[];
}

const OpenApiVisibilitySchema: z.ZodType<OpenApiVisibility> = z.union([
  z.literal("private"),
  z.object({ scope: z.string().optional(), value: z.string().optional() }),
]);

export const OpenApiShapeSchema: z.ZodType<OpenApiShape> = z.lazy(() =>
  z.object({
    $ref: z.string().optional(),
    description: z.string().optional(),
    type: z.union([z.string(), z.array(z.string())]).optional(),
    format: z.string().optional(),
    default: JsonValueSchema.optional(),
    enum: z.array(JsonValueSchema).optional(),
    readOnly: z.boolean().optional(),
    items: OpenApiShapeSchema.optional(),
    minItems: z.number().int().nonnegative().optional(),
    maxItems: z.number().int().nonnegative().optional(),
    properties: z.record(z.string(), OpenApiShapeSchema).optional(),
    required: z.array(z.string()).optional(),
    oneOf: z.array(OpenApiShapeSchema).optional(),
    anyOf: z.array(OpenApiShapeSchema).optional(),
    allOf: z.array(OpenApiShapeSchema).optional(),
    "x-aventure-visibility": OpenApiVisibilitySchema.optional(),
    "x-aventure-cli-conflicts": z
      .array(z.array(z.string().min(1)).min(2))
      .min(1)
      .optional(),
  }),
);

export const OpenApiParameterSchema = z.object({
  in: z.string(),
  name: z.string(),
  required: z.boolean().optional(),
  description: z.string().optional(),
  schema: OpenApiShapeSchema.optional(),
  "x-aventure-visibility": OpenApiVisibilitySchema.optional(),
});

export const OpenApiContentSchema = z.record(
  z.string(),
  z.object({ schema: OpenApiShapeSchema.optional() }),
);

export const OpenApiResponseEntrySchema = z.object({
  description: z.string().optional(),
  content: OpenApiContentSchema.optional(),
});

export const OpenApiRequestBodySchema = z.object({
  description: z.string().optional(),
  required: z.boolean().optional(),
  content: OpenApiContentSchema.optional(),
});

export const OpenApiToolExtensionSchema = z
  .object({
    auth: z.enum(["none"]).optional(),
    cli: z.string().optional(),
    cliAlias: z.string().optional(),
  })
  .optional();

const OpenApiJsonPointerSchema = z.union([
  z.literal(""),
  z.string().regex(/^(?:\/(?:[^~/]|~[01])*)+$/),
]);

export const OpenApiMutationReadbackSchema = z.strictObject({
  readOperationId: z.string().min(1),
  writePointer: OpenApiJsonPointerSchema,
  readPointer: OpenApiJsonPointerSchema,
});

const CompositeCommandSchema = z
  .string()
  .trim()
  .regex(/^[a-z0-9]+(?:-[a-z0-9]+)* [a-z0-9]+(?:-[a-z0-9]+)*$/u);
const CompositeOptionKeySchema = z.string().regex(/^[a-z][A-Za-z0-9]*$/u);
const CompositeLocalFlagSchema = z.string().regex(/^--(?:no-)?[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/u);

export const OpenApiCliCompositeExtensionSchema = z
  .strictObject({
    command: CompositeCommandSchema,
    role: z.enum(OPENAPI_CLI_COMPOSITE_ROLES),
    bodyOption: z.array(CompositeOptionKeySchema).min(1).optional(),
    localOption: z
      .array(
        z.strictObject({
          optionKey: CompositeOptionKeySchema,
          flag: CompositeLocalFlagSchema,
          description: z.string().trim().min(1),
        }),
      )
      .min(1)
      .optional(),
  })
  .superRefine((extension, context) => {
    const duplicate = [
      extension.bodyOption ?? [],
      (extension.localOption ?? []).map((option) => option.optionKey),
      (extension.localOption ?? []).map((option) => option.flag),
    ].some((entry) => new Set(entry).size !== entry.length);
    const mismatchedFlag = (extension.localOption ?? []).some(
      (option) => new Option(option.flag).attributeName() !== option.optionKey,
    );
    if (duplicate || mismatchedFlag) {
      context.addIssue({
        code: "custom",
        message: "Composite CLI options must be unique and match their local flags",
      });
    }
  })
  .optional();

export const OpenApiOperationSchema = z.object({
  operationId: z.string(),
  summary: z.string().optional(),
  description: z.string().optional(),
  tags: z.array(z.string()).optional(),
  deprecated: z.boolean().optional(),
  hidden: z.boolean().optional(),
  security: z.array(z.record(z.string(), z.array(z.string()))).optional(),
  parameters: z.array(OpenApiParameterSchema).optional(),
  requestBody: OpenApiRequestBodySchema.optional(),
  responses: z.record(z.string(), OpenApiResponseEntrySchema),
  "x-aventure-visibility": OpenApiVisibilitySchema.optional(),
  "x-aventure-tool": OpenApiToolExtensionSchema,
  "x-aventure-mutation-readback": OpenApiMutationReadbackSchema.optional(),
  "x-aventure-cli-composite": OpenApiCliCompositeExtensionSchema,
});

export const OpenApiPathOpsSchema = z.object(
  Object.fromEntries(OPENAPI_METHODS.map((method) => [method, OpenApiOperationSchema.optional()])),
);

export interface OpenApiComponent extends OpenApiShape {
  readonly properties?: Record<string, OpenApiShape>;
}

export const OpenApiComponentSchema: z.ZodType<OpenApiComponent> = z.object({
  $ref: z.string().optional(),
  description: z.string().optional(),
  type: z.union([z.string(), z.array(z.string())]).optional(),
  format: z.string().optional(),
  default: JsonValueSchema.optional(),
  enum: z.array(JsonValueSchema).optional(),
  readOnly: z.boolean().optional(),
  items: OpenApiShapeSchema.optional(),
  minItems: z.number().int().nonnegative().optional(),
  maxItems: z.number().int().nonnegative().optional(),
  oneOf: z.array(OpenApiShapeSchema).optional(),
  anyOf: z.array(OpenApiShapeSchema).optional(),
  allOf: z.array(OpenApiShapeSchema).optional(),
  properties: z.record(z.string(), OpenApiShapeSchema).optional(),
  required: z.array(z.string()).optional(),
  "x-aventure-visibility": OpenApiVisibilitySchema.optional(),
  "x-aventure-cli-conflicts": z
    .array(z.array(z.string().min(1)).min(2))
    .min(1)
    .optional(),
});

export const OpenApiDocumentSchema = z.object({
  tags: z.array(z.object({ name: z.string(), description: z.string().optional() })).optional(),
  paths: z.record(z.string(), OpenApiPathOpsSchema),
  components: z.object({ schemas: z.record(z.string(), OpenApiComponentSchema) }),
});

export type OpenApiParameter = z.infer<typeof OpenApiParameterSchema>;
export type OpenApiContent = z.infer<typeof OpenApiContentSchema>;
export type OpenApiResponseEntry = z.infer<typeof OpenApiResponseEntrySchema>;
export type OpenApiRequestBody = z.infer<typeof OpenApiRequestBodySchema>;
export type OpenApiToolExtension = z.infer<typeof OpenApiToolExtensionSchema>;
export type OpenApiMutationReadback = z.infer<typeof OpenApiMutationReadbackSchema>;
export type OpenApiCliCompositeExtension = z.infer<typeof OpenApiCliCompositeExtensionSchema>;
export type OpenApiCliCompositeRole = (typeof OPENAPI_CLI_COMPOSITE_ROLES)[number];
export type OpenApiCliCompositeLocalOption = NonNullable<
  NonNullable<OpenApiCliCompositeExtension>["localOption"]
>[number];
export type OpenApiOperation = z.infer<typeof OpenApiOperationSchema>;
export type OpenApiPathOps = z.infer<typeof OpenApiPathOpsSchema>;
export type OpenApiDocument = z.infer<typeof OpenApiDocumentSchema>;

export interface OpenApiLocatedOperation {
  readonly method: OpenApiMethod;
  readonly template: string;
  readonly operation: OpenApiOperation;
}
export type OpenApiSearchParams = Record<
  string,
  ResultEnvelopeScalar | readonly ResultEnvelopeScalar[] | undefined
>;

const PAGE_PARAMETER = new Set(["page", "size", "sort"]);

export function parseOpenApiDocument(text: string): OpenApiDocument {
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid OpenAPI document: ${message}`, { cause: error });
  }
  const result = OpenApiDocumentSchema.safeParse(parsed);
  if (!result.success) throw new Error(`Invalid OpenAPI document: ${result.error.message}`);
  return result.data;
}

export function findOperationByOperationId(
  paths: OpenApiDocument["paths"],
  operationId: string,
): OpenApiLocatedOperation | null {
  for (const [template, item] of Object.entries(paths)) {
    for (const method of OPENAPI_METHODS) {
      const operation = item[method];
      if (operation?.operationId === operationId) return { method, template, operation };
    }
  }
  return null;
}

export function resolveOpenApiEndpoint(
  paths: OpenApiDocument["paths"],
  method: OpenApiMethod,
  path: string,
): OpenApiLocatedOperation | null {
  const querylessPath = pathWithoutQuery(path);
  const exact = paths[querylessPath]?.[method];
  if (exact) return { method, template: querylessPath, operation: exact };
  for (const [template, item] of Object.entries(paths)) {
    const operation = item[method];
    if (operation && templateMatches(template, querylessPath)) {
      return { method, template, operation };
    }
  }
  return null;
}

export function buildOpenApiTemplatePath(
  template: string,
  pathParams: Record<string, string | number>,
  operationLabel = template,
): string {
  return template.replace(/\{([^}]+)}/g, (...args: [string, string, number, string]) => {
    const rawName = args[1];
    const value = pathParams[rawName];
    if (value == null) {
      throw new Error(`Missing path parameter '${rawName}' for ${operationLabel}`);
    }
    return encodeURIComponent(String(value));
  });
}

export function pathWithoutQuery(path: string): string {
  return new URL(path, "https://placeholder.invalid").pathname;
}

export function operationFilterMetadata(
  operation: OpenApiOperation,
  searchParams: OpenApiSearchParams | undefined,
): ResultEnvelopeFilters | undefined {
  const filters: ResultEnvelopeFilters = {};
  for (const parameter of operation.parameters ?? []) {
    if (parameter.in !== "query" || PAGE_PARAMETER.has(parameter.name)) continue;
    const value = searchParams?.[parameter.name] ?? scalarDefault(parameter.schema?.default);
    if (value !== undefined) filters[parameter.name] = value;
  }
  return Object.keys(filters).length === 0 ? undefined : filters;
}

function templateMatches(template: string, path: string): boolean {
  const templateParts = template.split("/").filter(Boolean);
  const pathParts = path.split("/").filter(Boolean);
  if (templateParts.length !== pathParts.length) return false;
  if (pathParts.some(isUnresolvedTemplateSegment)) return false;
  return templateParts.every(
    (templatePart, index) =>
      isOpenApiTemplateSegment(templatePart) || templatePart === pathParts[index],
  );
}

function isOpenApiTemplateSegment(pathSegment: string): boolean {
  const innerSegment = pathSegment.slice(1, -1);
  return (
    pathSegment.startsWith("{") &&
    pathSegment.endsWith("}") &&
    innerSegment.length > 0 &&
    !innerSegment.includes("/") &&
    !innerSegment.includes("{") &&
    !innerSegment.includes("}")
  );
}

function isUnresolvedTemplateSegment(pathSegment: string): boolean {
  if (isOpenApiTemplateSegment(pathSegment)) return true;
  const lowerSegment = pathSegment.toLowerCase();
  const innerSegment = pathSegment.slice(3, -3);
  return (
    lowerSegment.startsWith("%7b") &&
    lowerSegment.endsWith("%7d") &&
    innerSegment.length > 0 &&
    !innerSegment.includes("/") &&
    !innerSegment.includes("%") &&
    !innerSegment.includes("{") &&
    !innerSegment.includes("}")
  );
}

function scalarDefault(value: JsonValue | undefined): ResultEnvelopeFilters[string] | undefined {
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
    return value;
  }
  if (
    Array.isArray(value) &&
    value.every(
      (item) => typeof item === "string" || typeof item === "number" || typeof item === "boolean",
    )
  ) {
    return value;
  }
  return undefined;
}
