import type {
  McpGenerationContract,
  OpenApiCommandParameter,
  OpenApiCommandSpec,
} from "./contract";
import type { McpGenerationParameter } from "./contract-parameter";
import type { McpGenerationBody } from "./request-body-contract";
import { administrationNamespace } from "../config/cli-help-policy";
import { readEnv } from "../api/env";

/**
 * The spec set visible to the process's current credentials. Evaluate lazily —
 * after startup auth materialization — so a saved-config ADMIN_API_KEY counts.
 */
export function visibleOpenApiCommandSpecsForCurrentAuth(
  specs: readonly OpenApiCommandSpec[],
): readonly OpenApiCommandSpec[] {
  return visibleOpenApiCommandSpecs(specs, (readEnv().adminApiKey?.trim().length ?? 0) > 0);
}

export function visibleOpenApiCommandSpecs(
  specs: readonly OpenApiCommandSpec[],
  includePrivate: boolean,
): readonly OpenApiCommandSpec[] {
  if (includePrivate) return specs;
  return specs
    .filter((spec) => !administrationNamespace(spec.cliPath[0]))
    .map(withoutAdministrationAlias)
    .map(withoutPrivateCommandParameters);
}

function withoutAdministrationAlias(spec: OpenApiCommandSpec): OpenApiCommandSpec {
  if (!administrationNamespace(spec.cliAliasPath?.[0])) return spec;
  return { ...spec, cliAliasPath: undefined };
}

export function visibleMcpGenerationContracts(
  contracts: readonly McpGenerationContract[],
  includePrivate: boolean,
): readonly McpGenerationContract[] {
  if (includePrivate) return contracts;
  return contracts.map(withoutPrivateContractParameters);
}

function withoutPrivateCommandParameters(spec: OpenApiCommandSpec): OpenApiCommandSpec {
  const parameters = spec.parameters.filter(publicCommandParameter);
  const bodyParameters = spec.bodyParameters.filter(publicCommandParameter);
  if (
    parameters.length === spec.parameters.length &&
    bodyParameters.length === spec.bodyParameters.length
  ) {
    return spec;
  }
  return { ...spec, parameters, bodyParameters };
}

function withoutPrivateContractParameters(contract: McpGenerationContract): McpGenerationContract {
  const parameter = contract.parameter.flatMap(withoutPrivateContractParameter);
  const requestBody = visibleRequestBody(contract.requestBody);
  if (sameParameter(parameter, contract.parameter) && requestBody === contract.requestBody) {
    return contract;
  }
  return { ...contract, parameter, ...(requestBody === undefined ? {} : { requestBody }) };
}

function visibleRequestBody(body: McpGenerationBody | undefined): McpGenerationBody | undefined {
  if (body === undefined) return undefined;
  const parameter = body.parameter.flatMap(withoutPrivateContractParameter);
  return sameParameter(parameter, body.parameter) ? body : { ...body, parameter };
}

function withoutPrivateContractParameter(
  parameter: McpGenerationParameter,
): readonly McpGenerationParameter[] {
  if (!publicContractParameter(parameter)) return [];
  const itemProperty = parameter.itemProperty?.filter(publicContractParameter);
  if (sameParameter(itemProperty, parameter.itemProperty)) return [parameter];
  return [
    {
      ...parameter,
      ...(itemProperty === undefined || itemProperty.length === 0 ? {} : { itemProperty }),
    },
  ];
}

const publicCommandParameter = (parameter: OpenApiCommandParameter): boolean =>
  parameter.visibility !== "private";

const publicContractParameter = (parameter: McpGenerationParameter): boolean =>
  parameter.visibility !== "private";

function sameParameter(
  left: readonly McpGenerationParameter[] | undefined,
  right: readonly McpGenerationParameter[] | undefined,
): boolean {
  if (left === right) return true;
  if (left?.length !== right?.length || left === undefined || right === undefined) return false;
  return left.every((parameter, index) => parameter === right[index]);
}
