const MIN_SAFE_INFLECTION_LENGTH = 2;

const STOP_WORDS = new Set([
  "a",
  "an",
  "the",
  "and",
  "or",
  "for",
  "to",
  "of",
  "in",
  "on",
  "at",
  "by",
  "with",
  "from",
  "into",
  "is",
  "are",
  "be",
  "do",
  "does",
  "how",
  "what",
  "which",
  "that",
  "this",
  "these",
  "those",
  "i",
  "me",
  "my",
  "we",
  "our",
  "you",
  "your",
  "it",
  "its",
  "please",
  "want",
  "need",
  "can",
  "could",
  "should",
  "would",
]);

const DELETE_VERBS = new Set([
  "delete",
  "remove",
  "destroy",
  "purge",
  "erase",
  "drop",
  "detach",
  "unlink",
]);
const WRITE_VERBS = new Set([
  "create",
  "add",
  "update",
  "edit",
  "set",
  "change",
  "modify",
  "upload",
  "attach",
  "merge",
  "link",
  "join",
  "write",
  "import",
  "publish",
  "verify",
]);
const READ_VERBS = new Set([
  "list",
  "get",
  "show",
  "view",
  "browse",
  "fetch",
  "read",
  "lookup",
  "find",
  "count",
  "inspect",
]);

export type QueryMutationIntent = "delete" | "write" | "read" | "neutral";

export function queryMutationIntent(tokens: ReadonlySet<string>): QueryMutationIntent {
  const has = (verbs: ReadonlySet<string>) => [...tokens].some((token) => verbs.has(token));
  if (has(DELETE_VERBS)) return "delete";
  if (has(WRITE_VERBS)) return "write";
  if (has(READ_VERBS)) return "read";
  return "neutral";
}

export function addWithInflections(values: Set<string>, raw: string): void {
  const token = normalize(raw);
  if (token.length === 0) return;
  values.add(token);
  addCandidate(values, singularCandidate(token), token);
  addCandidate(values, pluralCandidate(token), token);
}

function singularCandidate(token: string): string | undefined {
  if (token === "people") return "person";
  const iesStem = token.endsWith("ies") ? token.slice(0, -"ies".length) : "";
  if (
    iesStem.length >= MIN_SAFE_INFLECTION_LENGTH &&
    !iesStem.endsWith("v") &&
    /[^aeiou]$/u.test(iesStem)
  ) {
    return `${token.slice(0, -"ies".length)}y`;
  }
  if (
    token.length > MIN_SAFE_INFLECTION_LENGTH &&
    token.endsWith("s") &&
    !token.endsWith("ss") &&
    !token.endsWith("us") &&
    token !== "news"
  ) {
    return token.slice(0, -1);
  }
  return undefined;
}

function pluralCandidate(token: string): string | undefined {
  if (token === "person") return "people";
  if (
    token.length >= MIN_SAFE_INFLECTION_LENGTH &&
    token.endsWith("y") &&
    /[^aeiou]y$/u.test(token)
  ) {
    return `${token.slice(0, -1)}ies`;
  }
  return token.endsWith("s") ? undefined : `${token}s`;
}

function addCandidate(values: Set<string>, candidate: string | undefined, token: string): void {
  if (
    candidate !== undefined &&
    candidate !== token &&
    candidate.length >= MIN_SAFE_INFLECTION_LENGTH &&
    /^[a-z]+$/u.test(candidate)
  ) {
    values.add(candidate);
  }
}

export function expandedTokens(normalizedQuery: string): ReadonlySet<string> {
  const tokens = new Set(meaningfulTokens(normalizedQuery));
  const base = Array.from(tokens);
  for (const token of base) addWithInflections(tokens, token);
  return tokens;
}

export function queryTermForms(query: string): readonly ReadonlySet<string>[] {
  return meaningfulTokens(query).map(expandedTokens);
}

export function coversEveryQueryTerm(
  termForm: readonly ReadonlySet<string>[],
  corpus: readonly string[],
): boolean {
  if (termForm.length === 0) return false;
  const corpusToken = expandedTokens(corpus.join(" "));
  return termForm.every((form) => [...form].some((candidate) => corpusToken.has(candidate)));
}

export function meaningfulTokens(value: string): string[] {
  return normalize(value)
    .split(/[^a-z0-9]+/u)
    .filter((token) => token.length > 0 && !STOP_WORDS.has(token));
}

export function normalize(raw: string): string {
  return raw
    .trim()
    .replace(/([a-z0-9])([A-Z])/gu, "$1 $2")
    .replace(/[_-]/gu, " ")
    .replace(/\s+/gu, " ")
    .toLowerCase();
}
