import type { OpenApiOperation, OpenApiSearchParams } from "./openapi-document";
import {
  failure,
  success,
  type ResultEnvelope,
  type ResultEnvelopeScalar,
} from "./result-envelope";

export type AgentClient = {
  readonly name?: string;
  readonly version?: string;
};

type AgentProvenanceEnv = Record<string, string | undefined>;
type SearchParamValue = ResultEnvelopeScalar | readonly ResultEnvelopeScalar[] | undefined;

type AgentPair = {
  readonly agentChassis: string;
  readonly agentModel: string;
};

type ChassisEnvSignal = {
  readonly chassis: string;
  readonly envNames: readonly string[];
};

type AgentPairCandidate =
  | { readonly status: "complete"; readonly pair: AgentPair }
  | { readonly status: "partial"; readonly warning: string }
  | { readonly status: "missing"; readonly warning: string };

const ACTOR_TYPE_PARAM = "actorType";
const AGENT_CHASSIS_PARAM = "agentChassis";
const AGENT_MODEL_PARAM = "agentModel";
const DIRECT_CHASSIS_ENV = "AVENTURE_AGENT_CHASSIS";
const DIRECT_MODEL_ENV = "AVENTURE_AGENT_MODEL";
const CHASSIS_ENV_SIGNALS = [
  { chassis: "kimi-cli", envNames: ["KIMI_MODEL"] },
  {
    chassis: "grok-build-cli",
    envNames: ["GROK_HOME", "GROK_MANAGED_BY_NPM", "GROK_MANAGED_BY_INTERNAL"],
  },
  { chassis: "claude-code", envNames: ["CLAUDECODE", "CLAUDE_CODE"] },
  {
    chassis: "codex-cli",
    envNames: ["CODEX_MANAGED_BY_NPM", "CODEX_SANDBOX", "CODEX_THREAD_ID", "CODEX_HOME"],
  },
] as const satisfies readonly ChassisEnvSignal[];
const MODEL_ENV_NAMES = [
  "KIMI_MODEL",
  "GROK_MODEL",
  "XAI_MODEL",
  "CODEX_MODEL",
  "OLLAMA_MODEL",
  "OLLAMA_LAUNCH_MODEL",
] as const;
const CLAUDE_MODEL_ENV_NAMES = [
  "ANTHROPIC_MODEL",
  "ANTHROPIC_DEFAULT_OPUS_MODEL",
  "ANTHROPIC_DEFAULT_SONNET_MODEL",
  "ANTHROPIC_DEFAULT_HAIKU_MODEL",
] as const;
const CHASSIS_TOKEN_PATTERN = /^[a-z][a-z0-9]*(-[a-z0-9]+)*-(cli|code|sdk|job)$/;
const CHASSIS_TOKEN_EXAMPLES =
  "claude-code, codex-cli, grok-build-cli, kimi-cli, hermes-cli, mistral-vibe-cli, mastra-sdk, spring-job";

export function operationRequiresAgentProvenance(operation: OpenApiOperation): boolean {
  const queryParams = operationQueryParams(operation);
  return (
    queryParams.has(ACTOR_TYPE_PARAM) ||
    (queryParams.has(AGENT_CHASSIS_PARAM) && queryParams.has(AGENT_MODEL_PARAM))
  );
}

export function resolveAgentProvenanceSearchParams({
  operation,
  searchParams,
  env = process.env,
  clientInfo,
}: {
  readonly operation: OpenApiOperation;
  readonly searchParams?: OpenApiSearchParams;
  readonly env?: AgentProvenanceEnv;
  readonly clientInfo?: AgentClient;
}): ResultEnvelope<OpenApiSearchParams | undefined | null> {
  if (!operationRequiresAgentProvenance(operation)) {
    return success("Agent provenance unchanged", searchParams);
  }

  const rawActor = paramString(searchParams?.[ACTOR_TYPE_PARAM]);
  const explicitActor = rawActor?.toLowerCase();
  if (rawActor && explicitActor !== "agent" && explicitActor !== "employee") {
    return failure(`${operation.operationId} has unknown provenance actorType.`, [
      "Use actorType=agent or actorType=employee. actorType is optional only at the API boundary when a complete agent pair or employee JWT lets the resolver infer it before domain and write-lane enforcement.",
    ]);
  }
  const explicitChassis = paramString(searchParams?.[AGENT_CHASSIS_PARAM]);
  const explicitModel = paramString(searchParams?.[AGENT_MODEL_PARAM]);
  if (explicitChassis && !CHASSIS_TOKEN_PATTERN.test(explicitChassis)) {
    return failure(
      `${operation.operationId} rejected: agentChassis '${explicitChassis}' is not a chassis token.`,
      [chassisTokenFormatGuidance(AGENT_CHASSIS_PARAM, explicitChassis)],
    );
  }
  if (explicitActor === "employee") {
    if (explicitChassis || explicitModel) {
      return failure(`${operation.operationId} has mixed employee and agent provenance.`, [
        "Pass actorType=employee without agentChassis or agentModel.",
      ]);
    }
    return success("Employee provenance explicit", {
      ...searchParams,
      actorType: "employee",
    });
  }

  const directChassisEnv = envValue(env, DIRECT_CHASSIS_ENV);
  const directModelEnv = envValue(env, DIRECT_MODEL_ENV);
  if (explicitChassis && directChassisEnv && explicitChassis !== directChassisEnv) {
    return failure(provenanceEnvConflictSummary(operation, "chassis"), [
      provenanceEnvConflictGuidance({
        param: AGENT_CHASSIS_PARAM,
        flag: "--agent-chassis",
        envName: DIRECT_CHASSIS_ENV,
        envValue: directChassisEnv,
        explicitValue: explicitChassis,
      }),
    ]);
  }
  if (explicitModel && directModelEnv && explicitModel !== directModelEnv) {
    return failure(provenanceEnvConflictSummary(operation, "model"), [
      provenanceEnvConflictGuidance({
        param: AGENT_MODEL_PARAM,
        flag: "--agent-model",
        envName: DIRECT_MODEL_ENV,
        envValue: directModelEnv,
        explicitValue: explicitModel,
      }),
    ]);
  }

  const candidate = resolveAgentPairCandidate(env, clientInfo);
  if (explicitChassis && explicitModel) {
    if (candidate.status === "partial") {
      return failure(
        `${operation.operationId} rejected: explicit agent provenance cannot repair partial runtime provenance.`,
        [
          candidate.warning,
          `You passed --agent-chassis ${explicitChassis} --agent-model ${explicitModel}.`,
          `Set ${DIRECT_CHASSIS_ENV} and ${DIRECT_MODEL_ENV} together after verifying the session; do not patch provenance per command.`,
        ],
      );
    }
    if (
      candidate.status === "complete" &&
      (explicitChassis !== candidate.pair.agentChassis ||
        explicitModel !== candidate.pair.agentModel)
    ) {
      return failure(
        `${operation.operationId} rejected: explicit agent provenance disagrees with the runtime environment.`,
        [
          `Detected ${candidate.pair.agentChassis}/${candidate.pair.agentModel} from runtime signals.`,
          `You passed --agent-chassis ${explicitChassis} --agent-model ${explicitModel}.`,
          "Omit both flags, or set AVENTURE_AGENT_CHASSIS and AVENTURE_AGENT_MODEL after verifying the session.",
        ],
      );
    }
    return success("Agent provenance explicit", {
      ...searchParams,
      actorType: "agent",
    });
  }
  if (explicitChassis || explicitModel) {
    return failure(agentPairRequiredSummary(operation), [
      "Pass both agentChassis and agentModel, or omit both so the API can infer an employee actor from an authenticated user JWT session or this caller can auto-fill a verified local agent pair.",
    ]);
  }

  if (candidate.status === "missing") {
    if (explicitActor === "agent") {
      return failure(agentPairRequiredSummary(operation), [
        "actorType=agent requires agentChassis and agentModel before the API can build the enforced domain actor.",
      ]);
    }
    return success("Provenance left for API-boundary actor inference", searchParams);
  }
  if (candidate.status === "partial") {
    return failure(agentPairRequiredSummary(operation), [
      candidate.warning,
      `Set ${DIRECT_CHASSIS_ENV} and ${DIRECT_MODEL_ENV}, or pass --agent-chassis and --agent-model.`,
    ]);
  }

  return success("Agent provenance auto-filled", {
    ...searchParams,
    actorType: "agent",
    agentChassis: candidate.pair.agentChassis,
    agentModel: candidate.pair.agentModel,
  });
}

function agentPairRequiredSummary(operation: OpenApiOperation): string {
  return `${operation.operationId} requires complete agent provenance.`;
}

function chassisTokenFormatGuidance(source: string, value: string): string {
  return [
    `${source}='${value}' is not a chassis identifier the backend's app.contracts.agent-provenance allowlist accepts.`,
    `Chassis tokens end in -cli, -code, -sdk, or -job — e.g. ${CHASSIS_TOKEN_EXAMPLES}.`,
    `Common mistakes: passing the bare model family ('grok' instead of 'grok-build-cli') or a truncated form ('grok-build' instead of 'grok-build-cli'). Fix the runtime export (or stop passing the explicit flag) — do not retry with cosmetic edits.`,
  ].join(" ");
}

function provenanceEnvConflictSummary(
  operation: OpenApiOperation,
  field: "chassis" | "model",
): string {
  return `${operation.operationId} rejected: explicit agent ${field} disagrees with the runtime environment.`;
}

function provenanceEnvConflictGuidance(args: {
  readonly param: string;
  readonly flag: string;
  readonly envName: string;
  readonly envValue: string;
  readonly explicitValue: string;
}): string {
  return [
    `Your runtime environment declares ${args.envName}=${args.envValue}, but you passed ${args.flag} ${args.explicitValue} (query param ${args.param}).`,
    `The environment value comes from the container/runtime you are executing inside and is almost always correct.`,
    `If you (the LLM agent) believe the environment is wrong, investigate the container configuration first — do not override with a guess.`,
    `Otherwise, omit ${args.flag} entirely and the CLI will auto-fill from ${args.envName} (and ${DIRECT_MODEL_ENV} for the model). LLM agents hallucinate provenance frequently; stop providing false parameters.`,
  ].join(" ");
}

function resolveAgentPairCandidate(
  env: AgentProvenanceEnv,
  clientInfo: AgentClient | undefined,
): AgentPairCandidate {
  const directChassis = envValue(env, DIRECT_CHASSIS_ENV);
  const directModel = envValue(env, DIRECT_MODEL_ENV);
  if (directChassis && !CHASSIS_TOKEN_PATTERN.test(directChassis)) {
    return {
      status: "partial",
      warning: chassisTokenFormatGuidance(DIRECT_CHASSIS_ENV, directChassis),
    };
  }
  if (directChassis && directModel) {
    return { status: "complete", pair: { agentChassis: directChassis, agentModel: directModel } };
  }
  if (directChassis || directModel) {
    return {
      status: "partial",
      warning: `${DIRECT_CHASSIS_ENV} and ${DIRECT_MODEL_ENV} must be set together.`,
    };
  }

  const chassis = detectChassis(env, clientInfo);
  const model = firstEnvValue(env, ...MODEL_ENV_NAMES) ?? claudeModel(env);
  if (chassis && model) {
    return { status: "complete", pair: { agentChassis: chassis, agentModel: model } };
  }
  if (chassis) {
    return {
      status: "partial",
      warning: `${chassis} was detected, but no verified model source was present.`,
    };
  }
  if (model) {
    return {
      status: "partial",
      warning: "A model was detected, but no verified agent chassis source was present.",
    };
  }
  return {
    status: "missing",
    warning: "No verified local agent chassis/model pair was present.",
  };
}

function detectChassis(
  env: AgentProvenanceEnv,
  clientInfo: AgentClient | undefined,
): string | undefined {
  const envSignal = CHASSIS_ENV_SIGNALS.find((signal) =>
    signal.envNames.some((name) => truthyEnv(env, name)),
  );
  return envSignal?.chassis ?? clientInfoChassis(clientInfo?.name);
}

function claudeModel(env: AgentProvenanceEnv): string | undefined {
  const values = [
    ...new Set(CLAUDE_MODEL_ENV_NAMES.map((name) => envValue(env, name)).filter(Boolean)),
  ];
  return values.length === 1 ? values[0] : undefined;
}

function clientInfoChassis(name: string | undefined): string | undefined {
  const normalized = name
    ?.toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
  if (!normalized) return undefined;
  if (normalized === "claude code" || normalized.includes("claude code")) return "claude-code";
  if (normalized === "codex" || normalized.includes("codex")) return "codex-cli";
  if (normalized === "kimi" || normalized.includes("kimi")) return "kimi-cli";
  if (normalized.includes("hermes")) return "hermes-cli";
  if (normalized.includes("grok")) return "grok-build-cli";
  if (normalized.includes("mistral vibe")) return "mistral-vibe-cli";
  return undefined;
}

const operationQueryParams = (operation: OpenApiOperation): Set<string> =>
  new Set(
    (operation.parameters ?? [])
      .filter((parameter) => parameter.in === "query")
      .map((parameter) => parameter.name),
  );

const firstEnvValue = (env: AgentProvenanceEnv, ...names: readonly string[]): string | undefined =>
  names.map((name) => envValue(env, name)).find((value) => value !== undefined);

function truthyEnv(env: AgentProvenanceEnv, name: string): boolean {
  const value = envValue(env, name)?.toLowerCase();
  return value !== undefined && value !== "0" && value !== "false" && value !== "no";
}

function envValue(env: AgentProvenanceEnv, name: string): string | undefined {
  return env[name]?.trim() || undefined;
}

function paramString(value: SearchParamValue): string | undefined {
  if (value === undefined) return undefined;
  const candidate = typeof value === "object" ? value[0] : value;
  if (candidate === undefined) return undefined;
  const text = String(candidate).trim();
  return text ? text : undefined;
}
