import type { JsonValue } from "@aventurevc/api-schemas/http/json-value";
import type { OpenApiOperation, OpenApiSearchParams } from "./openapi-document";
import type { ResultEnvelopeScalar } from "./result-envelope";

export type PrivateReadbackMode = "none" | "preferred" | "required";

export function privateReadbackMode(
  operation: OpenApiOperation,
  searchParams: OpenApiSearchParams | undefined,
  body?: JsonValue,
): PrivateReadbackMode {
  const bodyPrivateVisibility =
    body !== null && typeof body === "object" && !Array.isArray(body)
      ? body.includePrivate
      : undefined;
  if (requestsPrivate(searchParams?.includePrivate) || requestsPrivate(bodyPrivateVisibility)) {
    return "required";
  }
  return (operation.parameters ?? []).some(
    (value) => value.in === "query" && value.name === "includePrivate",
  )
    ? "preferred"
    : "none";
}

function requestsPrivate(value: JsonValue | readonly ResultEnvelopeScalar[] | undefined): boolean {
  if (value === null || typeof value === "object") {
    return Array.isArray(value) && value.some(requestsPrivate);
  }
  return (
    value === true ||
    value === 1 ||
    (typeof value === "string" && /^(true|on|yes|1)$/i.test(value.trim()))
  );
}
