import type { OpenApiDocument, OpenApiParameter, OpenApiShape } from "../api/openapi-document";
import {
  parameterVisibility,
  schemaDefault,
  schemaRefName,
  schemaType,
  schemaVisibility,
  stringEnum,
  valueSchema,
} from "./openapi-binding";

export type McpGenerationParameterLocation = "path" | "query" | "body";
export type McpGenerationParameterVisibility = "private";

type McpGenerationParameterBase = {
  readonly name: string;
  readonly inputName: string;
  readonly in: McpGenerationParameterLocation;
  readonly required: boolean;
  readonly description: string;
  readonly schemaRef?: string;
  readonly schemaType?: string;
  readonly schemaFormat?: string;
  readonly schemaDefault?: string | number | boolean | readonly string[];
  readonly schemaEnum?: readonly string[];
  readonly visibility?: McpGenerationParameterVisibility;
  readonly itemSchemaRef?: string;
  readonly itemSchemaType?: string;
  readonly itemSchemaFormat?: string;
  readonly itemSchemaEnum?: readonly string[];
};

export type McpGenerationQueryItemProperty = Omit<McpGenerationParameterBase, "in"> & {
  readonly in: "query";
};

export type McpGenerationParameter = McpGenerationParameterBase & {
  readonly itemProperty?: readonly McpGenerationQueryItemProperty[];
};

export function toContractParameter(
  openApi: OpenApiDocument,
  parameter: OpenApiParameter,
  usedNames: Set<string>,
): McpGenerationParameter {
  const schema = valueSchema(openApi, parameter.schema);
  const itemSchema = valueSchema(openApi, schema.items);
  const schemaRef = schemaRefName(schema);
  const visibility = schemaVisibility(schema) ?? parameterVisibility(openApi, parameter, schema);
  const location = parameterLocation(parameter.in);
  // For multipart endpoints whose JSON-typed body part is the canonical "body" wrapper, the
  // generator recurses through `body.<field>` paths so the api-caller can reassemble the nested
  // object before sending it as the JSON part. The `body.` segment is a transport detail; CLI
  // flags drop it to match the JSON-only endpoint's flag set verbatim.
  const inputBase = location === "body" ? stripBodyPartPrefix(parameter.name) : parameter.name;
  return {
    name: parameter.name,
    inputName: safeInputName(inputBase, location, usedNames),
    in: location,
    required: parameter.required ?? false,
    description: parameter.description ?? schema.description ?? "",
    schemaRef,
    schemaType: schemaType(schema),
    schemaFormat: schema.format,
    schemaDefault: schemaDefault(schema.default),
    schemaEnum: stringEnum(schema.enum),
    ...(visibility === undefined ? {} : { visibility }),
    itemSchemaRef: schemaRefName(schema.items),
    itemSchemaType: schemaType(itemSchema),
    itemSchemaFormat: itemSchema.format,
    itemSchemaEnum: stringEnum(itemSchema.enum),
    itemProperty: objectArrayItemProperty(openApi, parameter, location, itemSchema, usedNames),
  };
}

export function cliParameterInputName(
  contract: { readonly intent?: string; readonly path: string },
  parameter: McpGenerationParameter,
): string {
  if (parameter.in === "body") return parameter.inputName;
  const special = SPECIAL_INPUT_NAMES.find(
    (entry) => parameter.inputName === entry.name && contract.path.includes(entry.path),
  );
  if (special !== undefined) return special.inputName;
  if (parameter.inputName !== "id" && parameter.inputName !== "slug") {
    return outputModeSafeInputName(compactCliInputName(parameter.inputName), parameter);
  }
  const owner = genericIdentityOwner(contract.path);
  return outputModeSafeInputName(
    compactCliInputName(`${owner}${capitalize(parameter.inputName)}`),
    parameter,
  );
}

export function cliBodyParameterInputName(
  contract: {
    readonly intent?: string;
    readonly path: string;
    readonly parameter: readonly McpGenerationParameter[];
  },
  parameter: McpGenerationParameter,
  usedInputName: ReadonlySet<string> = pathQueryInputNames(contract),
): string {
  return uniqueBodyInputName(bodyParameterInputName(contract, parameter), new Set(usedInputName));
}

export function uniqueBodyInputName(inputName: string, usedInputName: Set<string>): string {
  if (!usedInputName.has(inputName)) return inputName;
  const base = `body${capitalize(inputName)}`;
  let candidate = base;
  for (let suffix = 2; usedInputName.has(candidate); suffix += 1) candidate = `${base}${suffix}`;
  return candidate;
}

function parameterLocation(value: string): McpGenerationParameterLocation {
  if (value === "path" || value === "query" || value === "body") return value;
  throw new Error(`Unsupported OpenAPI parameter location '${value}'.`);
}

function stripBodyPartPrefix(name: string): string {
  // Multipart endpoints carry the JSON-typed wrapper part as the canonical "body" form field; the
  // generator emits child parameter names as `body.<path>` so the api-caller can rebuild the
  // nested object before sending. CLI flags strip the wrapper segment so they match the JSON-only
  // endpoint's flag set exactly.
  const prefix = "body.";
  return name.startsWith(prefix) ? name.slice(prefix.length) : name;
}

function objectArrayItemProperty(
  openApi: OpenApiDocument,
  parameter: OpenApiParameter,
  location: McpGenerationParameterLocation,
  itemSchema: OpenApiShape,
  usedNames: Set<string>,
): readonly McpGenerationQueryItemProperty[] | undefined {
  if (location !== "query" || schemaType(itemSchema) !== "object") return undefined;
  const entries = Object.entries(itemSchema.properties ?? {}).flatMap(([name, schema]) => {
    const resolved = valueSchema(openApi, schema);
    if (!isCliQueryScalar(resolved)) return [];
    const child = toContractParameter(
      openApi,
      {
        name: `${parameter.name}[].${name}`,
        in: parameter.in,
        required: Boolean(parameter.required && itemSchema.required?.includes(name)),
        description: schema.description ?? resolved.description,
        schema,
      },
      usedNames,
    );
    return [{ ...child, name: `${parameter.name}[0].${name}`, in: "query" as const }];
  });
  return entries.length === 0 ? undefined : entries.toSorted(compareRangeBoundProperty);
}

function isCliQueryScalar(schema: OpenApiShape): boolean {
  return CLI_QUERY_SCALAR_TYPES.has(schemaType(schema) ?? "");
}

function compareRangeBoundProperty(
  left: McpGenerationQueryItemProperty,
  right: McpGenerationQueryItemProperty,
): number {
  return rangeBoundOrder(left.name) - rangeBoundOrder(right.name);
}

function rangeBoundOrder(name: string): number {
  const leaf = name.split(".").at(-1);
  if (leaf === "min") return 0;
  if (leaf === "max") return 1;
  return 2;
}

function safeInputName(
  name: string,
  location: McpGenerationParameterLocation,
  usedNames: Set<string>,
): string {
  const base =
    name
      .replace(/^[^A-Za-z0-9]+|[^A-Za-z0-9]+$/gu, "")
      .replace(/[^A-Za-z0-9]+([A-Za-z0-9])/gu, (...match) => String(match[1]).toUpperCase())
      .replace(/^./u, (first) => first.toLowerCase()) || "parameter";
  const prefixed = /^[A-Za-z_]/u.test(base)
    ? base
    : `parameter${base.replace(/^./u, (first) => first.toUpperCase())}`;
  let candidate = prefixed;
  if (usedNames.has(candidate)) {
    const locationPrefixed = `${location}${prefixed.replace(/^./u, (first) =>
      first.toUpperCase(),
    )}`;
    if (!usedNames.has(locationPrefixed)) candidate = locationPrefixed;
  }
  let index = 2;
  while (usedNames.has(candidate)) {
    candidate = `${prefixed}${index}`;
    index += 1;
  }
  usedNames.add(candidate);
  return candidate;
}

function genericIdentityOwner(path: string): string {
  return GENERIC_IDENTITY_OWNER.find(([, pattern]) => pattern.test(path))?.[0] ?? "record";
}

function bodyParameterInputName(
  contract: { readonly intent?: string; readonly path: string },
  parameter: McpGenerationParameter,
): string {
  if (parameter.name === "id" && contract.path === "/v1/app/url-slug-redirects") return "recordId";
  const compact = compactBodyCliInputName(parameter);
  const searchInput =
    contract.intent === "search" &&
    (parameter.name.startsWith("filter.") || parameter.name.startsWith("search."))
      ? compactCliInputName(
          compact.replace(/^(?:filter|search)/u, "").replace(/^./u, (first) => first.toLowerCase()),
        )
      : compact;
  return outputModeSafeInputName(searchInput, parameter);
}

function pathQueryInputNames(contract: {
  readonly intent?: string;
  readonly path: string;
  readonly parameter: readonly McpGenerationParameter[];
}): Set<string> {
  return new Set(
    contract.parameter
      .filter((toolParameter) => toolParameter.in === "path" || toolParameter.in === "query")
      .map((toolParameter) => cliParameterInputName(contract, toolParameter)),
  );
}

function capitalize(value: string): string {
  return value.replace(/^./u, (first) => first.toUpperCase());
}

function compactCliInputName(inputName: string): string {
  return inputName
    .replace(/^addressAddress/u, "address")
    .replace(/^arrayFilterAmountInvestedRange/u, "fundraiseAmountInvestedRange")
    .replace(/^arrayFilterAmountRaisedRange/u, "fundraiseAmountRaisedRange")
    .replace(/^arrayFilterEntityName$/u, "entityName")
    .replace(/^arrayFilterInvestedCompany$/u, "fundraiseInvestedCompanyName")
    .replace(/^arrayFilterPersonTitle$/u, "personTitle")
    .replace(/^arrayFilterRound$/u, "fundraiseRound")
    .replace(/^arrayFilterTotalInvestmentCount/u, "totalInvestmentCount")
    .replace(/^arrayFilterTypeRecord$/u, "typeRecord")
    .replace(/^createEntity/u, "entity")
    .replace(/^createUrlLink/u, "urlLink")
    .replace(/^fundraiseActivity/u, "fundraise")
    .replace(/FundraiseActivity/gu, "Fundraise")
    .replace(/^logoOption/u, "logo")
    .replace(/LogoOption/gu, "Logo")
    .replace(/^researchDetailTypeResearchDetail$/u, "researchDetailType")
    .replace(/^researchDetailValueResearchDetail$/u, "researchDetailValue")
    .replace(/^textText$/u, "text")
    .replace(/^textTextName$/u, "textName")
    .replace(/^textTextType$/u, "textType");
}

function compactBodyCliInputName(parameter: McpGenerationParameter): string {
  const compact = compactCliInputName(parameter.inputName);
  if (/(?:^|\.)nameAlias\[\]\./u.test(parameter.name)) {
    return compact.replace(/^entityNameAlias/u, "alias");
  }
  if (/(?:^|\.)urlLink\[\]\./u.test(parameter.name)) {
    return compactUrlLinkInputName(compact);
  }
  if (/(?:^|\.)manualLogo\./u.test(parameter.name)) {
    return compact.replace(/^manualLogo/u, "logo");
  }
  return compact;
}

function compactUrlLinkInputName(inputName: string): string {
  if (inputName === "urlLinkUrl") return "url";
  if (inputName === "urlLinkUrlType") return "urlType";
  return inputName.replace(/^urlLink/u, "url");
}

function outputModeSafeInputName(inputName: string, parameter: McpGenerationParameter): string {
  if (inputName !== "text") return inputName;
  return /(?:^|\.)text(?:\[\])?\.text$/u.test(parameter.name) ? "textBody" : "inputText";
}

const SPECIAL_INPUT_NAMES = [
  { name: "detailId", path: "/research/details/{detailId}", inputName: "researchDetailId" },
  { name: "detailId", path: "/financial/valuation/{detailId}", inputName: "valuationDetailId" },
  {
    name: "joinId",
    path: "/fundraise-investor-joins",
    inputName: "fundraiseInvestorJoinId",
  },
] as const;

const GENERIC_IDENTITY_OWNER: readonly [owner: string, pattern: RegExp][] = [
  ["entity", /^\/v1\/entities(?:$|\/detail|\/duplicate-check)/u],
  ["person", /^\/v1\/people(?:\/detail|\/duplicate-check|\/\{slug\})/u],
  ["news", /^\/v1\/(?:news(?:\/detail|\/duplicate-check|\/similar|\/\{id\})|jobs\/news\/)/u],
  ["screenshot", /^\/v1\/media\/screenshots\//u],
  ["media", /^\/v1\/media/u],
  ["article", /^\/v1\/app\/blog\/articles/u],
  ["page", /^\/v1\/app\/pages/u],
  ["contact", /^\/v1\/contacts\//u],
  ["provenance", /^\/v1\/provenance\//u],
  ["location", /^\/v1\/addresses\/locations\//u],
];

const CLI_QUERY_SCALAR_TYPES = new Set(["boolean", "integer", "number", "string"]);
